"""Edit distance and nearest-candidate lookup, for "did you mean" style hints."""


def levenshtein(a, b):
    """Minimum number of insertions, deletions and substitutions that turn a into b."""
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i]
        for j, cb in enumerate(b, 1):
            cost = 0 if ca == cb else 1
            current.append(min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + cost))
        previous = current
    return previous[-1]


def closest(word, candidates, max_distance=2):
    """The candidate nearest to word within max_distance; the first one wins a tie. None if none qualifies."""
    if max_distance < 0:
        raise ValueError(f"max_distance must not be negative: {max_distance}")
    best, best_distance = None, None
    for candidate in candidates:
        distance = levenshtein(word, candidate)
        if distance <= max_distance and (best_distance is None or distance < best_distance):
            best, best_distance = candidate, distance
    return best

